actions.script:
// Java subtracts days on the user's calendar; this subtracts whole days of milliseconds from now
const nowMillis = ec.user.timestampMillis(ec.user.nowTimestamp)
const basisTimestamp = new Date(nowMillis - daysToKeep * 86400000).toISOString()
const cf = ec.entity.conditionFactory
// Delete children of old conversations first so the LlmMessage FK cannot fail the job.
// A conversation that never got a message has no lastMessageDate, so it ages by createdDate.
const oldConvs = ec.entity.find("moqui.llm.LlmConversation")
        .condition(cf.makeCondition([
            cf.makeCondition("lastMessageDate", "<", basisTimestamp),
            cf.makeCondition([
                cf.makeCondition("lastMessageDate", "=", null),
                cf.makeCondition("createdDate", "<", basisTimestamp)
            ], "and")
        ], "or"))
        .disableAuthz().list()
const oldIds = [...oldConvs].map(conv => conv.conversationId).filter(id => id)
callLogsRemoved = 0
messagesRemoved = 0
conversationsRemoved = 0
contentStripped = 0
// Chunked so one IN list never exceeds a database limit (Oracle allows 1000)
for (let start = 0; start < oldIds.length; start += 500) {
    const chunk = oldIds.slice(start, start + 500)
    callLogsRemoved += ec.entity.find("moqui.llm.LlmCallLog")
            .condition("conversationId", "in", chunk).disableAuthz().deleteAll()
    messagesRemoved += ec.entity.find("moqui.llm.LlmMessage")
            .condition("conversationId", "in", chunk).disableAuthz().deleteAll()
    conversationsRemoved += ec.entity.find("moqui.llm.LlmConversation")
            .condition("conversationId", "in", chunk).disableAuthz().deleteAll()
}
messagesRemoved += ec.entity.find("moqui.llm.LlmMessage")
        .condition("sentDate", "less-than", basisTimestamp).disableAuthz().deleteAll()
callLogsRemoved += ec.entity.find("moqui.llm.LlmCallLog")
        .condition("startDate", "less-than", basisTimestamp).disableAuthz().deleteAll()
ec.entity.find("moqui.llm.LlmSkillUse")
        .condition("usedDate", "less-than", basisTimestamp).disableAuthz().deleteAll()
if (contentDaysToKeep && contentDaysToKeep > 0 && contentDaysToKeep < daysToKeep) {
    const contentBasis = new Date(nowMillis - contentDaysToKeep * 86400000).toISOString()
    // Only rows that still carry text, so a rerun does not touch rows it already stripped
    contentStripped = ec.entity.find("moqui.llm.LlmCallLog")
            .condition("startDate", "less-than", contentBasis)
            .condition(cf.makeCondition([
                cf.makeCondition("requestJson", "!=", null),
                cf.makeCondition("responseJson", "!=", null)
            ], "or"))
            .disableAuthz().updateAll({requestJson: null, responseJson: null})
}
ec.logger.log("info", `Removed ${callLogsRemoved} LlmCallLog, ${messagesRemoved} LlmMessage, ${conversationsRemoved} LlmConversation records more than ${daysToKeep} days old; stripped prompt and response text from ${contentStripped} call logs more than ${contentDaysToKeep} days old`)
